TIME = 'Time'
CRNTI_DL = 'ETtiTraceDlParUe_cRnti'
CRNTI_UL = 'ETtiTraceUlParUe_cRnti'


class LteTtiTrace(object):
    def __init__(self):
        """list of field/column names"""
        self._fields = {}
        self._broken = False

    def parse(self, header, trace):
        for name, value in zip(header, trace):
            self._fields[name] = value

        self._check_if_broken()
        return self

    def _check_if_broken(self):  # noqa: C901
        """
        based on `_check_if_broken` from ta_cit_tti.tti_analyzer.tti_traces.py

        """

        if self.get(TIME) != '':
            try:
                crnti = self.get(CRNTI_DL)
            except KeyError:
                crnti = self.get(CRNTI_UL)

            # if '-' in crnti:
            #     self._broken = True

            # in broken traces, crnti column might be "NewTx" or "ReTx: 1"
            try:
                int(crnti)
            except ValueError:
                self._broken = True

            if crnti == '65534':
                self._broken = True

    def get(self, name):
        """ might raise KeyError """
        return self._fields[name]

    @property
    def broken(self):
        return self._broken


class LteTtiTraceParser(object):
    def __init__(self, file_content):
        self.pre_header = []
        self.header = []
        self.all_traces = []

        file_content_as_list = self._prepare_file_content(file_content)
        self._set_pre_header_and_header(file_content_as_list)
        self._set_traces(file_content_as_list)

    @staticmethod
    def _prepare_file_content(content):
        if '\r\n' in content:
            return content.split('\r\n')
        else:
            return content.split('\n')

    def _set_pre_header_and_header(self, file_content):
        try:
            self.pre_header = file_content[0].split(',')
            self.header = file_content[1].split(',')
        except IndexError:
            pass

    def _set_traces(self, file_content):
        try:
            self.all_traces = [trace.split(',') for trace in file_content[2:] if trace]  # the last trace may be empty
        except IndexError:
            pass


class LteTtiTraceContainer(object):
    def __init__(self):
        self.traces = []
        self.direction = None

    def import_from_trace_parser(self, trace_parser, filter_out_broken=True):
        """
        filter_out_broken: flag determining if broken TTI traces will be omitted (those having '-' as cRnti)
        """
        pre_header = trace_parser.pre_header
        header = trace_parser.header

        for trace in trace_parser.all_traces:
            self._add(header, trace)

        if filter_out_broken:
            self.traces = [trace for trace in self.traces if not trace.broken]

        self.direction = 'UL' if 'UL_WMP' in pre_header else 'DL'
        return self

    def _add(self, header, trace):
        parsed_trace = LteTtiTrace().parse(header, trace)
        self.traces.append(parsed_trace)

    def traces_for_ue(self, ue):
        crnti_name = {'DL': CRNTI_DL,
                      'UL': CRNTI_UL}.get(self.direction)

        for trace in self.traces:
            if trace.get(crnti_name) == ue:
                yield trace

    def get_list_of_crntis(self):
        crnti_name = {'DL': CRNTI_DL,
                      'UL': CRNTI_UL}.get(self.direction)

        crntis = set()
        for trace in self.traces:
            crntis.add(trace.get(crnti_name))

        for ue in crntis.copy():
            try:
                int(ue)
            except (TypeError, ValueError):
                crntis.discard(ue)
        return sorted(list(crntis), key=int)

    def __iter__(self):
        for trace in self.traces:
            yield trace

    def __len__(self):
        return len(self.traces)

    def __getitem__(self, idx):
        return self.traces[idx]
